 local inspect=HolyStorm.PolicyUI:Button(p,L["ANALYSIS"],100,function()Page:Inspect()end);inspect:SetPoint("TOPLEFT",14,-100);local scroll,text=HolyStorm.PolicyUI:CreateTextPanel(p);scroll:SetPoint("TOPLEFT",14,-132);scroll:SetPoint("BOTTOMRIGHT",-28,18);self.output=text;HolyStorm.UI:RegisterPage("policyInspector",p,L["INSPECTOR_TITLE"],function()Page:Inspect()end,{"HS_POLICY_UPDATED","HS_PERMISSIONS_REVISION_REJECTED","HS_PERMISSIONS_CONFLICT_DETECTED","HS_PERMISSIONS_RECOVERY_REQUIRED"});HolyStorm.UI:AddNavigation("policyInspector",17,"Interface\\Icons\\INV_Misc_Eye_01",L["INSPECTOR_TITLE"],L["INSPECTOR_DESC"],function()HolyStorm.UI:ShowPage("policyInspector")end)
